/* style.css */
@layer components {
  .btn { @apply inline-flex h-11 items-center gap-2 rounded-lg px-4 font-semibold transition; }
  .btn-utama { @apply bg-emerald-600 text-white hover:bg-emerald-700; }
  .btn-bahaya { @apply bg-rose-600 text-white hover:bg-rose-700; }
  .konten-cms a { @apply text-emerald-700 underline underline-offset-2; }
}

<!-- HTML -->
<button class="btn btn-utama">Simpan</button>
<button class="btn btn-bahaya">Hapus</button>

/* style.css (Tailwind v4) */
@import "tailwindcss";

@theme {
  --font-sans: "Plus Jakarta Sans", ui-sans-serif, system-ui, sans-serif;
  --color-merek-50:  oklch(0.97 0.02 165);
  --color-merek-500: oklch(0.62 0.16 165);
  --color-merek-700: oklch(0.45 0.119 165);
  --radius-kartu: 1.25rem;
  --breakpoint-3xl: 120rem;
}

/* Hasilnya langsung tersedia: */
<div class="rounded-kartu bg-merek-50 font-sans text-merek-700 3xl:p-12">...</div>

/* Tema per pelanggan (white-label) cukup menimpa variabel */
[data-brand="kopi"] { --color-merek-500: oklch(0.55 0.12 50); }

